import os, re, json

def load_demo_data():
    # Load all grids from session log
    d = os.environ['RLM_SESSION_DIR']
    sessions_path = os.path.join(d, '..', 'sessions')
    session_file = os.path.basename(d) + '.jsonl'

    if os.path.exists(sessions_path):
        with open(os.path.join(sessions_path, session_file)) as f:
            text = f.read()
    else:
        return {}

    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', text):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = []
        rest = text[m.end():].split('\n')[:h]
        for r in rest:
            rows.append([int(x) for x in r.split()])
        if k not in G and len(rows) == h and all(len(r) == w for r in rows):
            G[k] = rows
    return G

G = load_demo_data()
print("Loaded grids:", sorted(G.keys()))

# Print demo input and output
for name in ['Demo pair 1 input', 'Demo pair 1 output']:
    for k in sorted(G.keys()):
        if name.replace(' ', '_') == k:
            print(f"\n{name}:")
            for row in G[k]:
                print(' '.join(str(c) for c in row))
